/**
 * Select the most frequent complete 8-bit RGB color at each pixel position.
 * Input frames must all be equal-length Uint8Array or Uint8ClampedArray
 * buffers. In a tie, the first color in frame order wins.
 * This synchronous CPU implementation holds the input frames in memory.
 */
export function modeRGB(frames) {
  validateFrames(frames, 3);
  return combine(frames, 3, frames[0].length / 3, false);
}

/**
 * Process browser ImageData objects. Only RGB is counted; the output is
 * opaque. Inputs must have identical positive width and height.
 */
function validateImages(images) {
  if (!Array.isArray(images) || images.length === 0) {
    throw new TypeError('Provide at least one ImageData frame');
  }
  const { width, height } = images[0] ?? {};
  if (!Number.isSafeInteger(width) || width <= 0 ||
      !Number.isSafeInteger(height) || height <= 0 ||
      !Number.isSafeInteger(width * height * 4)) {
    throw new RangeError('Image dimensions must be positive safe integers');
  }
  const frames = images.map((image) => {
    if (!image || image.width !== width || image.height !== height) {
      throw new RangeError('All image dimensions must match');
    }
    if (!(image.data instanceof Uint8ClampedArray) || image.data.length !== width * height * 4) {
      throw new TypeError('Each image must contain 8-bit RGBA ImageData');
    }
    return image.data;
  });
  if (typeof ImageData === 'undefined') {
    throw new Error('ImageData is unavailable in this environment; use modeRGB instead');
  }
  return { frames, width, height };
}

export function modeImageData(images) {
  const { frames, width, height } = validateImages(images);
  return new ImageData(combine(frames, 4, width * height, true), width, height);
}

/**
 * Process ImageData asynchronously with WebGPU or a CPU fallback.
 * processor: 'auto' (default), 'webgpu', or 'cpu'. Alpha is ignored.
 */
export async function modeStack(images, options = {}) {
  const { frames, width, height } = validateImages(images);
  const { processor = 'auto', signal, onProgress, batchPixels } = options;
  if (!['auto', 'webgpu', 'cpu'].includes(processor)) throw new TypeError('Invalid processor');
  if (onProgress !== undefined && typeof onProgress !== 'function') throw new TypeError('onProgress must be a function');
  if (batchPixels !== undefined && (!Number.isSafeInteger(batchPixels) || batchPixels < 1)) throw new RangeError('batchPixels must be a positive integer');
  checkAbort(signal);
  let callbackError;
  const reportProgress = onProgress && ((value) => {
    try { onProgress(value); } catch (error) { callbackError = { error }; throw error; }
  });
  if (processor !== 'cpu') {
    try {
      const { modeWebGPU } = await import('./webgpu.js');
      const data = await modeWebGPU(frames, width * height, { signal, onProgress: reportProgress, batchPixels });
      return new ImageData(data, width, height);
    } catch (error) {
      if (callbackError) throw callbackError.error;
      if (processor === 'webgpu' || signal?.aborted || error?.name === 'AbortError') throw error;
    }
  }
  const count = width * height, result = new Uint8ClampedArray(count * 4);
  const chunk = Math.min(batchPixels ?? 2048, 2048);
  for (let start = 0; start < count; start += chunk) {
    checkAbort(signal);
    const length = Math.min(chunk, count - start);
    combineRange(frames, 4, start, length, result, true);
    if (reportProgress) reportProgress({ processor: 'cpu', completed: start + length, total: count });
    await new Promise((resolve) => setTimeout(resolve, 0));
  }
  checkAbort(signal);
  return new ImageData(result, width, height);
}

/**
 * Decode browser File/Blob objects one at a time into temporary origin-private
 * storage, then process horizontal strips. Requires createImageBitmap,
 * OffscreenCanvas, ImageData and OPFS. The caller must supply frames in order.
 */
export async function modeFiles(files, options = {}) {
  if (!Array.isArray(files) || files.length === 0 || files.some(f => !(f instanceof Blob))) {
    throw new TypeError('Provide a non-empty array of image File or Blob objects');
  }
  const { signal, onProgress, processor = 'auto', maxWorkingMemoryBytes = 64 * 1024 * 1024, stripRows } = options;
  if (!['auto', 'webgpu', 'cpu'].includes(processor)) throw new TypeError('Invalid processor');
  if (onProgress !== undefined && typeof onProgress !== 'function') throw new TypeError('onProgress must be a function');
  if (!Number.isSafeInteger(maxWorkingMemoryBytes) || maxWorkingMemoryBytes < 1) throw new RangeError('Invalid working memory budget');
  if (stripRows !== undefined && (!Number.isSafeInteger(stripRows) || stripRows < 1)) throw new RangeError('stripRows must be positive');
  if (!globalThis.navigator?.storage?.getDirectory || typeof createImageBitmap !== 'function' || typeof OffscreenCanvas === 'undefined' || typeof ImageData === 'undefined') {
    throw new Error('File processing requires browser image decoding, OffscreenCanvas, ImageData and origin-private storage');
  }
  checkAbort(signal);
  const root = await navigator.storage.getDirectory();
  const name = `mode-stack-${crypto.randomUUID()}.tmp`;
  let handle, writer;
  try {
    handle = await root.getFileHandle(name, { create: true });
    writer = await handle.createWritable();
    let width = 0, height = 0;
    for (let i = 0; i < files.length; i++) {
      checkAbort(signal);
      const bitmap = await createImageBitmap(files[i]);
      try {
        if (i === 0) { width = bitmap.width; height = bitmap.height; }
        if (bitmap.width !== width || bitmap.height !== height) throw new RangeError('All image dimensions must match');
        const canvas = new OffscreenCanvas(width, height);
        const context = canvas.getContext('2d', { willReadFrequently: true });
        if (!context) throw new Error('Could not create an image decoding canvas');
        context.drawImage(bitmap, 0, 0);
        const data = context.getImageData(0, 0, width, height).data;
        await writer.write(data);
      } finally { bitmap.close(); }
      if (onProgress) onProgress({ phase: 'prepare', completed: i + 1, total: files.length });
    }
    await writer.close(); writer = undefined;
    const file = await handle.getFile();
    const rowBytes = width * 4;
    const memoryRows = Math.floor(maxWorkingMemoryBytes / (rowBytes * files.length));
    if (memoryRows < 1) throw new RangeError('Working memory budget is too small for one row across all frames');
    const rows = Math.min(height, stripRows ?? memoryRows, memoryRows);
    const result = new Uint8ClampedArray(width * height * 4);
    for (let y = 0; y < height; y += rows) {
      checkAbort(signal);
      const h = Math.min(rows, height - y), length = rowBytes * h, frames = [];
      for (let f = 0; f < files.length; f++) {
        checkAbort(signal);
        const offset = f * rowBytes * height + y * rowBytes;
        const bytes = await file.slice(offset, offset + length).arrayBuffer();
        if (bytes.byteLength !== length) throw new Error('Temporary image data is incomplete');
        frames.push(new ImageData(new Uint8ClampedArray(bytes), width, h));
      }
      let usedProcessor;
      const strip = await modeStack(frames, { processor, signal, onProgress: p => { usedProcessor = p.processor; } });
      result.set(strip.data, y * rowBytes);
      if (onProgress) onProgress({ phase: 'process', processor: usedProcessor, completed: y + h, total: height });
    }
    return new ImageData(result, width, height);
  } finally {
    if (writer) { try { await writer.abort(); } catch { /* Preserve the original error. */ } }
    if (handle) { try { await root.removeEntry(name); } catch { /* Browser may already have removed it. */ } }
  }
}

function checkAbort(signal) {
  if (signal?.aborted) throw new DOMException('Processing cancelled', 'AbortError');
}

function validateFrames(frames, channels) {
  if (!Array.isArray(frames) || frames.length === 0) {
    throw new TypeError('Provide at least one frame');
  }
  const size = frames[0]?.length;
  if (!Number.isSafeInteger(size) || size === 0 || size % channels !== 0) {
    throw new RangeError('Frames must contain whole, non-empty RGB pixels');
  }
  for (const frame of frames) {
    if (!(frame instanceof Uint8Array || frame instanceof Uint8ClampedArray)) {
      throw new TypeError('Frames must be Uint8Array or Uint8ClampedArray');
    }
    if (frame.length !== size) throw new RangeError('Frame sizes must match');
  }
}

function combine(frames, stride, pixels, opaqueOutput) {
  const result = opaqueOutput ? new Uint8ClampedArray(pixels * 4) : new Uint8Array(pixels * 3);
  combineRange(frames, stride, 0, pixels, result, opaqueOutput);
  return result;
}

function combineRange(frames, stride, start, pixels, result, opaqueOutput) {
  const counts = new Map();
  for (let p = start; p < start + pixels; p++) {
    counts.clear();
    let best = 0, bestCount = 0, bestFirst = frames.length;
    const offset = p * stride;
    for (let i = 0; i < frames.length; i++) {
      const frame = frames[i];
      const color = (frame[offset] << 16) | (frame[offset + 1] << 8) | frame[offset + 2];
      let entry = counts.get(color);
      if (entry === undefined) { entry = { count: 0, first: i }; counts.set(color, entry); }
      entry.count++;
      if (entry.count > bestCount || (entry.count === bestCount && entry.first < bestFirst)) {
        best = color; bestCount = entry.count; bestFirst = entry.first;
      }
    }
    const out = p * (opaqueOutput ? 4 : 3);
    result[out] = best >>> 16; result[out + 1] = (best >>> 8) & 255; result[out + 2] = best & 255;
    if (opaqueOutput) result[out + 3] = 255;
  }
}
